{
  "claims": [
    {
      "claim": "Direct rifampicin measurements demonstrate meaningful brain entry: human peritumoral brain tissue reached 0.29 µg/mL after i.v. infusion, monkey brain reached 0.87 µg/g after i.v. [14C]rifampicin, and baboon PET brain concentrations were around 1 µg/mL and were estimated to exceed the MIC by 3- to 4-fold.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-2",
        "Record 12-3",
        "Record 12-4",
        "Record 12-6"
      ]
    },
    {
      "claim": "Rifampicin and/or its metabolites were reported to penetrate the BBB in baboons, and high mouse brain concentrations (10.25 µg/mL) were measured after i.p. dosing, supporting meaningful CNS exposure after systemic administration.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-5",
        "Record 12-6"
      ]
    },
    {
      "claim": "In TBM and inflamed-meninges settings, the related rifamycin rifabutin achieved meaningful CNS exposure: CSF/plasma ratio ~0.227 and brain/plasma ratio ~0.856 in a rabbit TBM model, and ~50% CSF penetration in HIV patients.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 13"
      ],
      "record_ids": [
        "Record 13-1",
        "Record 13-2",
        "Record 13-6",
        "Record 13-9"
      ]
    },
    {
      "claim": "Rifabutin also reached dose-dependent CSF concentrations of 0.33–2.26 µg/mL in experimental meningitis, confirming that rifamycin-class antibiotics can achieve adequate CNS exposure under meningeal inflammation.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 13"
      ],
      "record_ids": [
        "Record 13-7"
      ]
    },
    {
      "claim": "There is negative rifamycin evidence: rifapentine was nearly undetectable in TBM patient CSF, rifampicin was labeled poorly BBB-penetrant in healthy baboons, rifabutin showed low rat brain radioactivity, and rifamycin SV/B showed limited or impermeable brain penetration; these indicate limited passive entry and efflux effects, but they are offset by direct rifampicin brain measurements and the enhanced CNS penetration expected in inflamed meninges.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 11",
        "Molecule 12",
        "Molecule 13",
        "Molecule 14",
        "Molecule 15"
      ],
      "record_ids": [
        "Record 11-1",
        "Record 12-1",
        "Record 13-4",
        "Record 13-10",
        "Record 14-2",
        "Record 14-3",
        "Record 15-1"
      ]
    },
    {
      "claim": "Efflux may limit rifamycin brain exposure, as shown by rifabutin P-gp efflux ratio 4.7 and rifaximin P-gp substrate status, but the endpoint definition requires meaningful rather than ideal access, and the measured rifampicin and rifabutin CSF/brain concentrations demonstrate that efflux is not absolute in the relevant disease setting.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 21",
        "Molecule 23"
      ],
      "record_ids": [
        "Record 21-1",
        "Record 23-1"
      ]
    }
  ],
  "final_prediction": "pass"
}

